import subprocess
import os
import random
import sys


def task_func(directory, file_list):
    if not file_list:
        return None

    candidates = []
    for file_name in file_list:
        path = os.path.join(directory, file_name)
        if os.path.isfile(path):
            candidates.append(path)

    if not candidates:
        return None

    selected_file = random.choice(candidates)

    try:
        if selected_file.lower().endswith(".py"):
            process = subprocess.Popen([sys.executable, selected_file], cwd=directory)
        else:
            process = subprocess.Popen([selected_file], cwd=directory)
    except (OSError, ValueError, subprocess.SubprocessError):
        return None

    return process.poll()
